import{j as g,aO as v,w as n,t as e,J as D,bB as k,I as h,F as r,aR as o,be as S,H as p,aT as f,aK as w,aH as B,aG as s,b5 as t,as as _,v as A}from"./index-BB7HNGy2.js";const C="https://visualizer.matthiasheckel.com/assets/mainboard-DjxlHjq-.png",i=d=>(w("data-v-24565829"),d=d(),B(),d),x={class:"hardware-page"},M={class:"page-shell"},E=p('<header class="hero" data-v-24565829><p class="eyebrow" data-v-24565829>MEDIENTECHNIK / ERSTES JAHR</p><h1 data-v-24565829>Hardwarekomponenten</h1><p class="lead" data-v-24565829>Die Bauteile eines Computers.<br data-v-24565829><span data-v-24565829>Was sie tun und wie sie zusammenarbeiten.</span></p></header><section class="assignment" aria-labelledby="assignment-title" data-v-24565829><p class="eyebrow" data-v-24565829>DEINE AUFGABE</p><h2 id="assignment-title" data-v-24565829>Visualisiere die Hardwarekomponenten eines Computers.</h2></section><nav class="jump" aria-label="Abschnitte dieser Seite" data-v-24565829><a href="#ueberblick" data-v-24565829>Kurzer Überblick</a><a href="#eva" data-v-24565829>Das Grundprinzip</a><a href="#bauteile" data-v-24565829>Die acht Begriffe</a><a href="#zusammenspiel" data-v-24565829>Der Aufbau</a></nav><section id="ueberblick" class="introduction" aria-labelledby="introduction-title" data-v-24565829><p class="eyebrow" data-v-24565829>KURZER ÜBERBLICK</p><h2 id="introduction-title" data-v-24565829>Was steckt in einem Computer?</h2><p data-v-24565829>Diese Seite erklärt, aus welchen Hardwarekomponenten ein Computer aufgebaut ist. Hardwarekomponenten sind die einzelnen Bauteile des Computers.</p><p data-v-24565829>Dieses Wissen hilft dir zum Beispiel, wenn du als Grafikdesignerin oder Grafikdesigner einen Computer kaufen möchtest. Du kannst dann besser einschätzen, wie leistungsfähig die einzelnen Bauteile für deine Arbeit sein sollten. Für große Bilder oder aufwendige Grafiken braucht ein Computer zum Beispiel genügend Arbeitsspeicher und passende Rechenleistung.</p><p data-v-24565829>In einem Computer arbeiten verschiedene Bauteile zusammen. Der <strong data-v-24565829>Prozessor (CPU)</strong> ist für das Rechnen zuständig. Der <strong data-v-24565829>Arbeitsspeicher (RAM)</strong> merkt sich die Daten, die gerade gebraucht werden. Auf der <strong data-v-24565829>Festplatte oder SSD</strong> werden Dateien dauerhaft gespeichert, zum Beispiel Bilder und Videos. Die <strong data-v-24565829>Grafikkarte (GPU)</strong> berechnet die Bilder, die auf dem Monitor angezeigt werden. Das <strong data-v-24565829>Mainboard</strong> verbindet alle Bauteile miteinander. Über die <strong data-v-24565829>Anschlüsse</strong> kannst du Geräte wie Maus, Tastatur, Monitor oder Drucker mit dem Computer verbinden.</p><p class="example" data-v-24565829><strong data-v-24565829>Vergleich:</strong> Stell dir einen Arbeitsplatz vor. Die CPU ist der Mitarbeiter, der die Aufgaben erledigt. Der RAM ist der Schreibtisch, auf dem alles liegt, was gerade gebraucht wird. Die SSD ist der Schrank, in dem Unterlagen aufbewahrt werden. Die Grafikkarte ist ein Spezialist, der sich um die Bilder kümmert.</p><p data-v-24565829>Die einzelnen Bauteile und ihre Aufgaben schauen wir uns gleich weiter unten genauer an.</p></section><section id="eva" aria-labelledby="eva-title" data-v-24565829><p class="eyebrow" data-v-24565829>01 / DAS GRUNDPRINZIP</p><h2 id="eva-title" data-v-24565829>Eingabe → Verarbeitung → Ausgabe</h2><p data-v-24565829>Hardware sind die Teile eines Computers, die du anfassen kannst. Software sind die Programme. Gemeinsam arbeiten sie nach dem <strong data-v-24565829>EVA-Prinzip</strong>:</p><div class="eva-grid" data-v-24565829><article data-v-24565829><span class="badge" data-v-24565829>E</span><h3 data-v-24565829>Eingabe</h3><p data-v-24565829>Du gibst Daten oder Befehle ein.</p><p class="example" data-v-24565829>Du klickst mit der Maus auf „Bild heller machen“.</p></article><article data-v-24565829><span class="badge" data-v-24565829>V</span><h3 data-v-24565829>Verarbeitung</h3><p data-v-24565829>Der Computer verarbeitet die Daten.</p><p class="example" data-v-24565829>Die CPU führt Befehle aus. Die Bilddaten liegen im RAM.</p></article><article data-v-24565829><span class="badge" data-v-24565829>A</span><h3 data-v-24565829>Ausgabe</h3><p data-v-24565829>Du siehst oder hörst das Ergebnis.</p><p class="example" data-v-24565829>Der Monitor zeigt das hellere Bild.</p></article></div></section>',5),z={id:"bauteile","aria-labelledby":"parts-title"},y=i(()=>e("p",{class:"eyebrow"},"02 / DIE ACHT BEGRIFFE",-1)),R=i(()=>e("h2",{id:"parts-title"},"Was macht welches Bauteil?",-1)),I={class:"parts-grid"},P={class:"eyebrow"},U={class:"verb"},H={class:"example"},F=i(()=>e("strong",null,"Beispiel",-1)),G={class:"sketch"},V=i(()=>e("strong",null,"Idee für deine Zeichnung:",-1)),N=p('<section class="memory" aria-labelledby="memory-title" data-v-24565829><p class="eyebrow" data-v-24565829>03 / MERKE DIR</p><h2 id="memory-title" data-v-24565829>RAM und Festplatte haben verschiedene Aufgaben.</h2><div class="pair" data-v-24565829><div data-v-24565829><h3 data-v-24565829>RAM = dein Arbeitstisch</h3><p data-v-24565829>Hier liegt, was du gerade bearbeitest. Ohne Strom ist der Inhalt weg.</p></div><div data-v-24565829><h3 data-v-24565829>Festplatte / SSD = dein Schrank</h3><p data-v-24565829>Hier bewahrst du gespeicherte Dateien auf. Sie bleiben auch ohne Strom erhalten.</p></div></div><p class="save" data-v-24565829><strong data-v-24565829>Speichern heißt:</strong> Du schreibst deine Arbeit als Datei auf die Festplatte oder SSD.</p></section>',1),T={id:"zusammenspiel",class:"overview","aria-labelledby":"overview-title"},O=i(()=>e("p",{class:"eyebrow"},"04 / DER AUFBAU",-1)),K=i(()=>e("h2",{id:"overview-title"},"Die Bauteile arbeiten zusammen.",-1)),L=i(()=>e("p",null,"Tippe auf eine Beschriftung im Bild. Darunter steht die Aufgabe des Bauteils.",-1)),$={class:"diagram-scroll",tabindex:"0","aria-label":"Komponentenbild; auf kleinen Bildschirmen seitlich scrollbar"},j={class:"diagram",role:"group","aria-label":"Anklickbare Hardwarekomponenten"},Z=["src"],W=["aria-label","aria-pressed","onClick"],J={id:"component-explanation",class:"diagram-detail","aria-live":"polite"},q=i(()=>e("p",{class:"caption"},"Die Pfeile zeigen vereinfacht den Datenaustausch. Auf kleinen Bildschirmen kannst du das Bild seitlich verschieben. Eine Festplatte oder SSD kann im Computer eingebaut oder extern angeschlossen sein.",-1)),Q=Object.assign({name:"HardwarekomponentenPage"},{__name:"Hardwarekomponenten",setup(d){const l=v("cpu"),b=[{id:"peripherals",label:"Eingabegeräte",x:1.2,y:1.8,w:21,h:8.2},{id:"board",label:"Mainboard / Motherboard",x:38.2,y:1.4,w:31.6,h:5.8},{id:"ports",label:"Schnittstellen",x:31.9,y:25.4,w:12.9,h:5.7},{id:"cpu",label:"Mikroprozessor (CPU)",x:49.8,y:16.7,w:13.8,h:7.6},{id:"ram",label:"Arbeitsspeicher (RAM)",x:78.8,y:20.2,w:14.1,h:7.5},{id:"io",label:"I/O-Controller",x:83.3,y:49,w:15.6,h:7.4},{id:"bus",label:"Bussystem",x:51.5,y:56.7,w:13.9,h:7.5},{id:"storage",label:"Festplatte / SSD",x:85.2,y:71.4,w:13.6,h:7.6},{id:"peripherals",label:"Ausgabegeräte",x:1.2,y:86,w:18.1,h:8.2}],c=[{id:"cpu",short:"CPU",name:"Mikroprozessor (CPU)",verb:"Rechnen und steuern",text:"Die CPU führt die Befehle der Programme aus. Sie berechnet Daten und steuert Abläufe im Computer.",example:"Du veränderst die Helligkeit eines Fotos. Die CPU verarbeitet die Befehle des Bildprogramms.",sketch:"Ein kleiner Chip auf dem Mainboard."},{id:"bus",short:"Bus",name:"Bussystem (Bus)",verb:"Informationen transportieren",text:"Der Bus verbindet Bauteile miteinander. Über diese Verbindungen laufen Daten, Speicheradressen und Steuersignale.",example:"Die CPU liest Bilddaten aus dem RAM. Die Daten werden über Verbindungen zwischen den Bauteilen übertragen.",sketch:"Linien mit Pfeilen zwischen den Bauteilen."},{id:"ram",short:"RAM",name:"Arbeitsspeicher (RAM)",verb:"Für die aktuelle Arbeit bereithalten",text:"Im RAM liegen die Programme und Daten, die gerade gebraucht werden. Der Zugriff ist schnell. Ohne Strom geht sein Inhalt verloren.",example:"Das geöffnete Bild wird im Arbeitsspeicher bearbeitet. Speichere deine Änderungen, bevor du den Computer ausschaltest.",sketch:"Ein schmaler Riegel mit mehreren kleinen Chips."},{id:"storage",short:"SSD",name:"Festplatte / SSD",verb:"Dauerhaft speichern",text:"Hier liegen Programme und gespeicherte Dateien. Sie bleiben auch ohne Strom erhalten. Eine Festplatte (HDD) speichert auf magnetischen Scheiben. Eine SSD speichert in Speicherchips.",example:"Du speicherst dein Foto als Datei. Beim nächsten Start kannst du es wieder öffnen.",sketch:"Eine Festplatte oder eine SSD mit der Beschriftung „Dateien“."},{id:"board",short:"Board",name:"Mainboard (Motherboard)",verb:"Bauteile verbinden",text:"Das Mainboard ist die Hauptplatine des Computers. Auf ihr sitzen oder stecken zum Beispiel CPU, RAM und Controller. Leiterbahnen verbinden die Bauteile.",example:"In einem Desktop-PC steckt der RAM in passenden Steckplätzen auf dem Mainboard.",sketch:"Eine große Platine als Grundlage für CPU, RAM und Verbindungen."},{id:"io",short:"I/O",name:"I/O-Controller",verb:"Ein- und Ausgabe steuern",text:"I/O steht für Input und Output: Eingabe und Ausgabe. Controller regeln den Datenaustausch mit angeschlossenen Geräten. Sie sind oft in andere Chips eingebaut.",example:"Ein USB-Controller regelt die Verbindung zu einer angeschlossenen USB-Maus.",sketch:"Ein kleiner Chip zwischen den inneren Bauteilen und den Anschlüssen."},{id:"peripherals",short:"Geräte",name:"Peripheriegeräte",verb:"Eingeben, ausgeben und speichern",text:"Diese Geräte ergänzen den Computer. Mit einer Tastatur gibst du Daten ein. Ein Monitor zeigt Ergebnisse. Ein USB-Stick speichert Dateien.",example:"Eingabe: Maus, Tastatur, Scanner, Mikrofon. Ausgabe: Monitor, Drucker, Lautsprecher. Speicher: USB-Stick, externe Festplatte.",sketch:"Geräte um den Computer herum. Beschrifte sie mit ihrer Aufgabe."},{id:"ports",short:"Ports",name:"Schnittstellen",verb:"Geräte anschließen",text:"Eine Schnittstelle ist eine Verbindung, über die Daten ausgetauscht werden. Anschlüsse und passende Kabel verbinden Geräte mit dem Computer.",example:"USB: Maus oder USB-Stick. HDMI: Bildschirm. Netzwerkanschluss (RJ45): Netzwerk. SATA: interne Festplatte oder SSD.",sketch:"Anschlüsse am Computer und Kabel zu den passenden Geräten."}];return(X,Y)=>{const m=f("RouterLink");return s(),n("main",x,[e("div",M,[D(m,{to:"/",class:"back"},{default:k(()=>[h("← Zur Startseite")]),_:1}),E,e("section",z,[y,R,e("div",I,[(s(),n(r,null,o(c,(a,u)=>e("article",{key:a.id,class:"part"},[e("p",P,t(String(u+1).padStart(2,"0"))+" / "+t(a.short),1),e("h3",null,t(a.name),1),e("p",U,t(a.verb),1),e("p",null,t(a.text),1),e("div",H,[F,e("p",null,t(a.example),1)]),e("p",G,[V,h(" "+t(a.sketch),1)])])),64))])]),N,e("section",T,[O,K,L,e("div",$,[e("div",j,[e("img",{src:S(C),width:"1536",height:"1024",alt:"Mainboard mit CPU, RAM, Bussystem, I/O-Controller, SSD und Schnittstellen. Links sind Maus, Tastatur, Scanner, Monitor und Drucker angeschlossen."},null,8,Z),(s(),n(r,null,o(b,a=>e("button",{key:a.label,type:"button",class:"hotspot","aria-label":`${a.label}: Erklärung anzeigen`,"aria-pressed":l.value===a.id,"aria-controls":"component-explanation",style:_({left:`${a.x}%`,top:`${a.y}%`,width:`${a.w}%`,height:`${a.h}%`}),onClick:u=>l.value=a.id},null,12,W)),64))])]),e("div",J,[(s(),n(r,null,o(c,a=>(s(),n(r,{key:a.id},[l.value===a.id?(s(),n(r,{key:0},[e("h3",null,t(a.name),1),e("p",null,t(a.text),1)],64)):A("",!0)],64))),64))]),q])])])}}}),ae=g(Q,[["__scopeId","data-v-24565829"]]);export{ae as default};
